DROP VIEW IF EXISTS vw_scale_regimes CASCADE;
DROP VIEW IF EXISTS vw_inference_runs CASCADE;
DROP VIEW IF EXISTS vw_observed_scales CASCADE;
DROP VIEW IF EXISTS vw_measurement_models CASCADE;
DROP VIEW IF EXISTS vw_system_stats CASCADE;
DROP VIEW IF EXISTS vw_scales CASCADE;
DROP VIEW IF EXISTS vw_systems CASCADE;

-- ----------------------------------------------------------------------------
-- vw_systems: Each row is a fractal or power-law system described in a common schema.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_systems CASCADE;
CREATE VIEW vw_systems WITH (security_invoker = ON) AS
SELECT
  t.system_id,                                                                  -- Primary key for the system.
  t.display_name,                                                               -- Human readable label.
  t.class,                                                                      -- High-level class: 'fractal' or 'power_law'.
  t.base_scale,                                                                 -- Reference scale x0 for iteration 0.
  t.scale_factor,                                                               -- Multiplicative change in scale per iteration.
  t.measure_name,                                                               -- What the measured quantity represents (count, perimeter, frequency, etc.).
  t.fractal_dimension,                                                          -- Fractal (Hausdorff / similarity) dimension where defined (geometric fractals). Null for purely statistical laws.
  t.theoretical_log_log_slope,                                                  -- Theoretical slope d(log Measure)/d(log Scale) for this system under the chosen definition of Scale.
  calc_systems_empirical_fit_quality(t.system_id) AS empirical_fit_quality,     -- R² value from fitted model showing how well observed data fits theory.
  calc_systems_empirical_slope_deviation(t.system_id) AS empirical_slope_deviation,-- Absolute magnitude of slope error from fitted observations.
  calc_systems_measurement_noise_level(t.system_id) AS measurement_noise_level, -- Noise sigma parameter from measurement model for this system.
  calc_systems_data_quality_score(t.system_id) AS data_quality_score,           -- Composite quality metric combining fit quality and slope accuracy.
  calc_systems_relative_slope_error(t.system_id) AS relative_slope_error,       -- Slope deviation as a fraction of theoretical slope (percentage error).
  calc_systems_is_high_quality_fit(t.system_id) AS is_high_quality_fit,         -- Boolean flag indicating excellent fit (R² > 0.99 and slope error < 0.05).
  calc_systems_scale_range_span(t.system_id) AS scale_range_span,               -- Total span in log-scale space covered by data (decades of scale).
  calc_systems_measure_range_span(t.system_id) AS measure_range_span            -- Total span in log-measure space covered by data (decades of measure).
FROM systems t;

-- ----------------------------------------------------------------------------
-- vw_scales: Generic log–log points for each system at multiple iterations / scales.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_scales CASCADE;
CREATE VIEW vw_scales WITH (security_invoker = ON) AS
SELECT
  t.scale_id,                                                                   -- Primary key for this scale measurement.
  t."system",                                                                   -- FK to systems table.
  t.iteration,                                                                  -- Discrete zoom level or rank index.
  t.measure,                                                                    -- Y-axis measured quantity at this scale.
  calc_scales_base_scale(t.scale_id) AS base_scale,                             -- Base scale looked up from parent system.
  calc_scales_scale_factor(t.scale_id) AS scale_factor,                         -- Scale factor looked up from parent system.
  calc_scales_scale_factor_power(t.scale_id) AS scale_factor_power,             -- ScaleFactor raised to the Iteration power.
  calc_scales_scale(t.scale_id) AS scale,                                       -- X-axis variable: BaseScale multiplied by ScaleFactorPower.
  calc_scales_log_scale(t.scale_id) AS log_scale,                               -- log10 of Scale.
  calc_scales_log_measure(t.scale_id) AS log_measure,                           -- log10 of Measure.
  t.is_projected,                                                               -- True if this data point is a projection/estimate rather than measured data.
  t.data_regime,                                                                -- Data regime for this point: 'ideal' (constructed/projection) or 'measured' (noisy real-world measurement).
  t.measurement_model,                                                          -- Optional FK to measurement_models describing noise/cutoff/discretization used to generate or interpret this point.
  calc_scales_theoretical_log_log_slope(t.scale_id) AS theoretical_log_log_slope,-- Theoretical slope from parent system for comparison.
  calc_scales_empirical_log_log_slope(t.scale_id) AS empirical_log_log_slope,   -- Empirical slope from system_stats for residual calculation.
  calc_scales_system_min_log_scale(t.scale_id) AS system_min_log_scale,         -- Minimum log scale for the system (for normalization).
  calc_scales_system_max_log_scale(t.scale_id) AS system_max_log_scale,         -- Maximum log scale for the system (for normalization).
  calc_scales_system_delta_log_scale(t.scale_id) AS system_delta_log_scale,     -- Total log scale range for the system.
  calc_scales_scale_ratio(t.scale_id) AS scale_ratio,                           -- How many times larger than base scale (multiplicative factor). Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_scales_log_scale_normalized(t.scale_id) AS log_scale_normalized          -- Position within system's log-scale range as 0-1 value. Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
FROM scales t;

-- ----------------------------------------------------------------------------
-- vw_system_stats: Statistical analysis of each system's log-log behavior, with rollups from scales and lookups to systems.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_system_stats CASCADE;
CREATE VIEW vw_system_stats WITH (security_invoker = ON) AS
SELECT
  t.system_stats_id,                                                            -- Primary key for this stats record.
  t."system",                                                                   -- FK to systems table.
  t.analysis_name,                                                              -- Human-readable name for this analysis run.
  t.status,                                                                     -- Status of analysis: draft, validated, published.
  calc_system_stats_system_display_name(t.system_stats_id) AS system_display_name,-- Display name looked up from parent system.
  calc_system_stats_theoretical_log_log_slope(t.system_stats_id) AS theoretical_log_log_slope,-- Theoretical slope looked up from parent system.
  calc_system_stats_point_count(t.system_stats_id) AS point_count,              -- Rollup: Count of scale measurements for this system.
  calc_system_stats_min_log_scale(t.system_stats_id) AS min_log_scale,          -- Rollup: Minimum log10(Scale) across child scales.
  calc_system_stats_max_log_scale(t.system_stats_id) AS max_log_scale,          -- Rollup: Maximum log10(Scale) across child scales.
  calc_system_stats_min_log_measure(t.system_stats_id) AS min_log_measure,      -- Rollup: Minimum log10(Measure) across child scales.
  calc_system_stats_max_log_measure(t.system_stats_id) AS max_log_measure,      -- Rollup: Maximum log10(Measure) across child scales.
  calc_system_stats_delta_log_measure(t.system_stats_id) AS delta_log_measure,  -- Calculated: Difference between min and max log measure (numerator for slope).
  calc_system_stats_delta_log_scale(t.system_stats_id) AS delta_log_scale,      -- Calculated: Difference between max and min log scale (denominator for slope).
  calc_system_stats_empirical_log_log_slope(t.system_stats_id) AS empirical_log_log_slope,-- Calculated: Slope of log-log line from empirical data. Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_system_stats_slope_error(t.system_stats_id) AS slope_error,              -- Calculated: Difference between empirical and theoretical slopes.
  calc_system_stats_fitted_slope(t.system_stats_id) AS fitted_slope,            -- Fitted slope from inference_runs on observed data.
  calc_system_stats_fitted_vs_empirical_delta(t.system_stats_id) AS fitted_vs_empirical_delta,-- Difference between fitted slope (noisy obs) and empirical slope (ideal data).
  calc_system_stats_r2(t.system_stats_id) AS r2,                                -- R² fit quality from inference_runs.
  calc_system_stats_quality_weighted_slope(t.system_stats_id) AS quality_weighted_slope,-- Fitted slope weighted by confidence (R²).
  calc_system_stats_residual_rms(t.system_stats_id) AS residual_rms,            -- RMS residual from fitted model.
  calc_system_stats_noise_sigma(t.system_stats_id) AS noise_sigma,              -- Noise level parameter from measurement model.
  calc_system_stats_slope_to_noise_ratio(t.system_stats_id) AS slope_to_noise_ratio,-- Signal-to-noise ratio (slope magnitude vs. noise level). Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_system_stats_deviation_score(t.system_stats_id) AS deviation_score,      -- Composite error metric from inference_runs.
  calc_system_stats_abs_delta_log_measure(t.system_stats_id) AS abs_delta_log_measure,-- Absolute value of delta log measure.
  calc_system_stats_log_log_area(t.system_stats_id) AS log_log_area,            -- Area in log-log space (product of ranges).
  calc_system_stats_data_density(t.system_stats_id) AS data_density,            -- Number of data points per unit area in log-log space. Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_system_stats_relative_slope_error(t.system_stats_id) AS relative_slope_error-- Slope error as fraction of theoretical slope (percentage). Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
FROM system_stats t;

-- ----------------------------------------------------------------------------
-- vw_measurement_models: Measurement/de-idealization specs used to produce or interpret real-world (noisy, finite-size, discretized) scale records.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_measurement_models CASCADE;
CREATE VIEW vw_measurement_models WITH (security_invoker = ON) AS
SELECT
  t.measurement_model_id,                                                       -- Primary key for this measurement model.
  t."system",                                                                   -- FK to systems table (measurement model is typically system-specific).
  t.data_regime,                                                                -- Regime this model describes. Usually 'measured'.
  t.scale_regime,                                                               -- Optional RegimeID this measurement model applies to
  t.noise_type,                                                                 -- Noise model applied to measures (e.g., lognormal multiplicative).
  t.noise_sigma,                                                                -- Noise strength parameter (e.g., sigma in log space for lognormal).
  t.cutoff_min_scale,                                                           -- Minimum scale included (finite-size / censoring lower bound).
  t.cutoff_max_scale,                                                           -- Maximum scale included (finite-size / censoring upper bound).
  t.discretization_type,                                                        -- How observations are discretized (none, rounding, binning, log-binning).
  t.discretization_param,                                                       -- Parameterization of discretization (e.g., decimals=2 or binwidth=log2).
  calc_measurement_models_mean_absolute_residual(t.measurement_model_id) AS mean_absolute_residual,-- Average absolute residual from fitted model for observations using this model.
  calc_measurement_models_outlier_count(t.measurement_model_id) AS outlier_count,-- Number of outlier points (|standardized residual| > 2.5) in observed_scales.
  calc_measurement_models_total_point_count(t.measurement_model_id) AS total_point_count,-- Total number of observed data points using this measurement model.
  calc_measurement_models_outlier_rate(t.measurement_model_id) AS outlier_rate, -- Fraction of points that are outliers (quality metric). Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_measurement_models_effective_point_count(t.measurement_model_id) AS effective_point_count,-- Number of non-outlier points (usable for analysis).
  calc_measurement_models_residual_rms_from_inference(t.measurement_model_id) AS residual_rms_from_inference,-- RMS residual from inference_runs (total fit error).
  calc_measurement_models_cutoff_log_min_scale(t.measurement_model_id) AS cutoff_log_min_scale,-- Log10 of minimum cutoff scale.
  calc_measurement_models_cutoff_log_max_scale(t.measurement_model_id) AS cutoff_log_max_scale,-- Log10 of maximum cutoff scale.
  calc_measurement_models_cutoff_range_span(t.measurement_model_id) AS cutoff_range_span-- Range of observable scales in log units (decades).
FROM measurement_models t;

-- ----------------------------------------------------------------------------
-- vw_observed_scales: Noisy, finite-range, discretized observations of each system's scaling law. Mirrors scales but with DataRegime='measured'.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_observed_scales CASCADE;
CREATE VIEW vw_observed_scales WITH (security_invoker = ON) AS
SELECT
  t.observed_scale_id,                                                          -- Primary key for this observed scale measurement.
  t."system",                                                                   -- FK to systems table.
  t.measurement_model,                                                          -- FK to measurement model used/assumed for this observation set.
  t.iteration,                                                                  -- Discrete zoom level or rank index.
  t.measure,                                                                    -- Observed (noisy) Y-axis quantity at this scale.
  calc_observed_scales_base_scale(t.observed_scale_id) AS base_scale,           -- Base scale looked up from parent system.
  calc_observed_scales_scale_factor(t.observed_scale_id) AS scale_factor,       -- Scale factor looked up from parent system.
  calc_observed_scales_scale_factor_power(t.observed_scale_id) AS scale_factor_power,-- ScaleFactor raised to the Iteration power.
  calc_observed_scales_scale(t.observed_scale_id) AS scale,                     -- X-axis variable: BaseScale multiplied by ScaleFactorPower.
  calc_observed_scales_log_scale(t.observed_scale_id) AS log_scale,             -- log10 of Scale.
  calc_observed_scales_log_measure(t.observed_scale_id) AS log_measure,         -- log10 of Measure.
  t.data_regime,                                                                -- Data regime. For observed_scales this is 'measured'.
  calc_observed_scales_fitted_slope(t.observed_scale_id) AS fitted_slope,       -- Fitted slope from inference_runs for this system.
  calc_observed_scales_fitted_intercept(t.observed_scale_id) AS fitted_intercept,-- Fitted intercept from inference_runs for this system.
  calc_observed_scales_residual_rms(t.observed_scale_id) AS residual_rms,       -- RMS residual from fitted model (for standardization).
  calc_observed_scales_predicted_log_measure(t.observed_scale_id) AS predicted_log_measure,-- Predicted log measure from fitted model.
  calc_observed_scales_residual(t.observed_scale_id) AS residual,               -- Vertical distance from fitted line in log-log space.
  calc_observed_scales_residual_squared(t.observed_scale_id) AS residual_squared,-- Squared residual for aggregation into RMS calculations.
  calc_observed_scales_standardized_residual(t.observed_scale_id) AS standardized_residual,-- Residual in units of RMS (number of standard deviations). Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_observed_scales_is_outlier(t.observed_scale_id) AS is_outlier,           -- Outlier detection flag (>2.5 RMS units from fit).
  calc_observed_scales_scale_ratio(t.observed_scale_id) AS scale_ratio,         -- Scale relative to base scale (multiplicative factor). Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_observed_scales_abs_residual(t.observed_scale_id) AS abs_residual        -- Absolute value of residual for aggregation.
FROM observed_scales t;

-- ----------------------------------------------------------------------------
-- vw_inference_runs: Inference outputs (fits and residual geometry) computed from observed_scales relative to each system fixed point.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_inference_runs CASCADE;
CREATE VIEW vw_inference_runs WITH (security_invoker = ON) AS
SELECT
  t.inference_run_id,                                                           -- Primary key for this inference run.
  t."system",                                                                   -- FK to systems table.
  t.data_regime,                                                                -- Regime of the fitted data (ideal/measured).
  t.measurement_model,                                                          -- FK to measurement model used/assumed (nullable for ideal).
  t.fit_method,                                                                 -- Fitting method used (e.g., OLS on log-log).
  t.point_count,                                                                -- Count of observed points used in fit (measured).
  t.theoretical_log_log_slope,                                                  -- Fixed-point slope for the system.
  t.fitted_slope,                                                               -- Estimated slope from observed data under FitMethod.
  t.fitted_intercept,                                                           -- Estimated intercept in log10 space (logMeasure = intercept + slope*logScale).
  t.slope_delta,                                                                -- Difference between fitted slope and fixed-point slope.
  t.r2,                                                                         -- Coefficient of determination for the log-log fit.
  t.residual_rms,                                                               -- Root-mean-square residual in log10 space (vertical residuals).
  t.residual_max_abs,                                                           -- Maximum absolute residual in log10 space.
  t.orthogonal_rms,                                                             -- RMS orthogonal distance to the fitted log-log line in (logScale, logMeasure) coordinates.
  t.deviation_score,                                                            -- Composite deviation score combining residual RMS and slope delta (units: log10 + slope).
  calc_inference_runs_slope_confidence_interval(t.inference_run_id) AS slope_confidence_interval,-- Approximate 95% confidence interval for slope (simplified formula). Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_inference_runs_min_log_scale(t.inference_run_id) AS min_log_scale,       -- Minimum log scale in the observed data.
  calc_inference_runs_max_log_scale(t.inference_run_id) AS max_log_scale,       -- Maximum log scale in the observed data.
  calc_inference_runs_min_log_measure(t.inference_run_id) AS min_log_measure,   -- Minimum log measure in the observed data.
  calc_inference_runs_max_log_measure(t.inference_run_id) AS max_log_measure,   -- Maximum log measure in the observed data.
  calc_inference_runs_log_measure_range(t.inference_run_id) AS log_measure_range,-- Range of log measure values.
  calc_inference_runs_abs_slope_delta(t.inference_run_id) AS abs_slope_delta,   -- Absolute value of slope delta.
  calc_inference_runs_slope_is_significant(t.inference_run_id) AS slope_is_significant,-- True if deviation from theory exceeds confidence interval (statistically significant).
  calc_inference_runs_one_plus_residual_rms(t.inference_run_id) AS one_plus_residual_rms,-- One plus residual RMS for efficiency calculation.
  calc_inference_runs_fit_efficiency(t.inference_run_id) AS fit_efficiency,     -- Quality per unit error (higher is better). Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_inference_runs_normalized_rmse(t.inference_run_id) AS normalized_rmse,   -- RMSE as fraction of total log measure range. Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_inference_runs_slope_to_theoretical_ratio(t.inference_run_id) AS slope_to_theoretical_ratio,-- Ratio of fitted to theoretical slope (1.0 = perfect match). Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_inference_runs_one_minus_r2(t.inference_run_id) AS one_minus_r2,         -- One minus R² for adjusted R² calculation.
  calc_inference_runs_point_count_minus_one(t.inference_run_id) AS point_count_minus_one,-- Point count minus one (degrees of freedom).
  calc_inference_runs_point_count_minus_two(t.inference_run_id) AS point_count_minus_two,-- Point count minus two (degrees of freedom for regression).
  calc_inference_runs_adjusted_r2(t.inference_run_id) AS adjusted_r2,           -- R² adjusted for degrees of freedom. Reads 0 when the denominator is 0 (the transpiler has no NULLIF).
  calc_inference_runs_residual_rms_squared(t.inference_run_id) AS residual_rms_squared,-- Squared residual RMS for BIC calculation.
  calc_inference_runs_log_residual_rms_squared(t.inference_run_id) AS log_residual_rms_squared,-- Log of squared residual RMS.
  calc_inference_runs_log_point_count(t.inference_run_id) AS log_point_count,   -- Natural log of point count.
  calc_inference_runs_bic(t.inference_run_id) AS bic                            -- Bayesian Information Criterion (lower is better fit).
FROM inference_runs t;

-- ----------------------------------------------------------------------------
-- vw_scale_regimes: Multi-regime analysis defining different scale ranges within systems where different slope behaviors may occur.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_scale_regimes CASCADE;
CREATE VIEW vw_scale_regimes WITH (security_invoker = ON) AS
SELECT
  t.regime_id,                                                                  -- Primary key for this regime.
  t."system",                                                                   -- FK to systems table.
  t.min_log_scale,                                                              -- Minimum log10(scale) boundary for this regime.
  t.max_log_scale,                                                              -- Maximum log10(scale) boundary for this regime.
  t.expected_slope,                                                             -- Expected log-log slope within this regime.
  t.regime_type,                                                                -- Type of regime: 'early_scaling', 'mature_scaling', 'crossover', 'cutoff', etc.
  calc_scale_regimes_regime_span(t.regime_id) AS regime_span,                   -- Width of regime in log-scale units (decades).
  calc_scale_regimes_regime_center(t.regime_id) AS regime_center,               -- Midpoint of regime in log-scale.
  calc_scale_regimes_theoretical_log_log_slope(t.regime_id) AS theoretical_log_log_slope,-- Global theoretical slope from parent system.
  calc_scale_regimes_slope_deviation_from_global(t.regime_id) AS slope_deviation_from_global,-- Local expected slope deviation from global theoretical slope.
  calc_scale_regimes_points_in_regime(t.regime_id) AS points_in_regime          -- Count of data points from scales table within this regime's range.
FROM scale_regimes t;



